using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
using UnityEngine.AddressableAssets.ResourceLocators;using UnityEngine.ResourceManagement;using UnityEngine.ResourceManagement.ResourceProviders;using UnityEngine.ResourceManagement.ResourceLocations;
using DelvePresentation;
public static class NativeCreatureReview {
 static string game="D:/Steam/steamapps/common/7 Days To Die";
 static Dictionary<string,AssetBundle> loaded=new Dictionary<string,AssetBundle>();
 static void LoadDependencies(IResourceLocation loc){foreach(var dep in loc.Dependencies??new List<IResourceLocation>())LoadDependencies(dep);string path=loc.InternalId.Replace("{AddressableFolders.RootDir}",game).Replace("{BundleTags.Tag}","");if(File.Exists(path)&&!loaded.ContainsKey(path)){var bundle=AssetBundle.LoadFromFile(path);if(bundle==null)throw new Exception("Bundle load failed "+path);loaded.Add(path,bundle);}}
 static string[] ids={"delveCorruptedWalker","delveImp","delvePossessedSoldier","delveDemonSpawn","delveWarpedBrute","delveAshboundWarden","delveHellhound","delveGloomcat","delveCrystalStag","delveThornbackBoar"};
 static string[] paths={"Entities/Zombies/Boe/ZBoe.prefab","Entities/Zombies/Spider/ZSpider.prefab","Entities/Zombies/Soldier/ZSoldier.prefab","Entities/Zombies/Joe/ZJoe.prefab","Entities/Zombies/Hawaiian/ZHawaiian.prefab","Entities/Zombies/Biker/ZBiker.prefab","Entities/Animals/Wolf/animalStandardDogZombieRagdoll.prefab","Entities/Animals/Cat/animalMountainLion.prefab","Entities/Animals/Deer/animalDeerStag.prefab","Entities/Animals/Boar/animalBoarPrefab.prefab"};
 public static void Run(){var report=new System.Text.StringBuilder();try{
  var data=JsonUtility.FromJson<ContentCatalogData>(File.ReadAllText(game+"/7DaysToDie_Data/StreamingAssets/aa/catalog.json").Replace("{AddressableFolders.RootDir}",game).Replace("{BundleTags.Tag}",""));var locator=data.CreateLocator("LocalNativeReview");var manager=new ResourceManager();manager.ResourceProviders.Add(new AssetBundleProvider());manager.ResourceProviders.Add(new BundledAssetProvider());manager.ResourceProviders.Add(new LegacyResourcesProvider());
  manager.InternalIdTransformFunc=loc=>loc.InternalId.Replace("{AddressableFolders.RootDir}",game).Replace("{BundleTags.Tag}","");
  var camera=new GameObject("NativeReviewCamera").AddComponent<Camera>();camera.enabled=false;camera.orthographic=true;camera.nearClipPlane=.01f;camera.farClipPlane=100;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.045f,.055f,.065f);
  RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.4f,.4f,.4f);var key=new GameObject("Key").AddComponent<Light>();key.type=LightType.Directional;key.intensity=1.2f;key.transform.rotation=Quaternion.Euler(35,-30,0);var fill=new GameObject("Fill").AddComponent<Light>();fill.type=LightType.Directional;fill.intensity=.55f;fill.color=new Color(.7f,.8f,1);fill.transform.rotation=Quaternion.Euler(20,130,0);
  string output=Path.GetFullPath("../NativeReview");Directory.CreateDirectory(output);
  for(int index=0;index<ids.Length;index++){
   string id=ids[index];File.WriteAllText("../Reports/native-review-progress.txt","LOADING "+id);IList<IResourceLocation> locations=null;object address=locator.Keys.FirstOrDefault(k=>k.ToString().EndsWith(paths[index],StringComparison.OrdinalIgnoreCase));if(address==null||!locator.Locate(address,typeof(GameObject),out locations))throw new Exception("Native address not found "+paths[index]);
   LoadDependencies(locations[0]);GameObject prefab=null;foreach(var bundle in loaded.Values){prefab=bundle.LoadAsset<GameObject>(locations[0].InternalId);if(prefab!=null)break;}if(prefab==null)throw new Exception("Native prefab null "+id+" "+locations[0].InternalId);var native=UnityEngine.Object.Instantiate(prefab);native.name="Native_"+id;foreach(var a in native.GetComponentsInChildren<Animator>(true))a.enabled=false;
   foreach(var lod in native.GetComponentsInChildren<LODGroup>(true))lod.ForceLOD(0);
   var originals=native.GetComponentsInChildren<Renderer>(true);var lease=new NativeBodyFoundation();lease.Apply(originals,id);report.AppendLine(id+" nativeShaderTintMaterials="+lease.TintedMaterials+" bodyRenderers="+originals.Length);
   // Preview normalization only: source game shaders require world-global state.
   var temps=new List<Material>();foreach(var renderer in originals){var mats=renderer.sharedMaterials;for(int i=0;i<mats.Length;i++){var src=mats[i];if(src==null)continue;report.AppendLine("MATERIAL "+src.shader.name+" "+String.Join(",",src.GetTexturePropertyNames()));var mat=new Material(Shader.Find("Standard"));mat.mainTexture=src.HasProperty("_Albedo")?src.GetTexture("_Albedo"):src.mainTexture;mat.SetFloat("_Glossiness",.25f);string normal=src.HasProperty("_Normal")?"_Normal":src.HasProperty("_BumpMap")?"_BumpMap":null;if(normal!=null&&src.GetTexture(normal)!=null){mat.SetTexture("_BumpMap",src.GetTexture(normal));mat.EnableKeyword("_NORMALMAP");}if(src.HasProperty("_Color"))mat.color=src.GetColor("_Color");mats[i]=mat;temps.Add(mat);}renderer.sharedMaterials=mats;}
   string group=index<6?"enemies":index<9?"quadrupeds":"thornback";var art=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/QualityPrefabs/"+group+"/"+id+".prefab"),native.transform,false);foreach(var a in art.GetComponentsInChildren<Animator>(true))a.enabled=false;
   var map=native.GetComponentsInChildren<Transform>(true).Where(t=>!t.IsChildOf(art.transform)).GroupBy(t=>t.name).ToDictionary(g=>g.Key,g=>g.First());var bind=EnemyRigs.Build(id);int pairs=0;
   var poses=new List<KeyValuePair<Transform,Matrix4x4>>();foreach(var bone in art.GetComponentsInChildren<Transform>(true)){Transform target;Matrix4x4 rest;if(map.TryGetValue(bone.name,out target)&&bind.TryGetValue(bone.name,out rest)){var offset=rest.inverse*art.transform.worldToLocalMatrix*bone.localToWorldMatrix;poses.Add(new KeyValuePair<Transform,Matrix4x4>(bone,target.localToWorldMatrix*offset));pairs++;}}foreach(var pair in poses)pair.Key.SetPositionAndRotation(pair.Value.GetColumn(3),pair.Value.rotation);
   if(pairs<25)throw new Exception("Native correspondence incomplete "+id+" "+pairs);art.GetComponent<LODGroup>().ForceLOD(0);
   var all=native.GetComponentsInChildren<Renderer>().Where(r=>r.enabled&&r.gameObject.activeInHierarchy).ToArray();var bounds=all[0].bounds;foreach(var r in all)bounds.Encapsulate(r.bounds);camera.orthographicSize=Mathf.Max(.1f,bounds.size.magnitude*.55f);
   string folder=Path.Combine(output,id);Directory.CreateDirectory(folder);int vi=0;foreach(var direction in new[]{new Vector3(1.3f,.5f,2.6f),new Vector3(-1.5f,.2f,2.6f),new Vector3(.7f,.5f,-2.8f)}){
    camera.transform.position=bounds.center+direction*Mathf.Max(2,bounds.size.magnitude);camera.transform.LookAt(bounds.center);var rt=new RenderTexture(768,768,24);camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;var texture=new Texture2D(768,768,TextureFormat.RGB24,false);texture.ReadPixels(new Rect(0,0,768,768),0,0);texture.Apply();File.WriteAllBytes(Path.Combine(folder,"view-"+(vi++)+".png"),texture.EncodeToPNG());RenderTexture.active=null;camera.targetTexture=null;UnityEngine.Object.DestroyImmediate(texture);rt.Release();UnityEngine.Object.DestroyImmediate(rt);
   }
   report.AppendLine("PASS "+id+" native bone pairs="+pairs+" marker="+NativeBodyFoundation.Enabled(art));lease.Dispose();UnityEngine.Object.DestroyImmediate(native);foreach(var mat in temps)UnityEngine.Object.DestroyImmediate(mat);foreach(var bundle in loaded.Values)bundle.Unload(true);loaded.Clear();EditorUtility.UnloadUnusedAssetsImmediate();
  }
  File.WriteAllText("../Reports/native-review.txt","PASS native asset correspondence and normalized previews\n"+report);EditorApplication.Exit(0);
 }catch(Exception e){Debug.LogException(e);File.WriteAllText("../Reports/native-review.txt","FAIL\n"+e+"\n"+report);EditorApplication.Exit(1);}}
}
